const text = $json.message.text || "";

if (text.startsWith("/call")) {
  const parts = text.split(" ");
  return {
    action: "make_call",
    phone: parts[1],
    firstMessage: parts.slice(2).join(" ") || "Calling regarding your interior requirement."
  };
}

if (text.startsWith("/status")) {
  return {
    action: "status",
    leadId: text.split(" ")[1]
  };
}

if (text.startsWith("/followup")) {
  return {
    action: "followup",
    followupTime: text.replace("/followup", "").trim()
  };
}

return { action: "none" };

// Safe getter helper
function safeGet(obj, path) {
  try {
    return path.split(".").reduce((acc, key) => acc?.[key], obj);
  } catch {
    return null;
  }
}

// STEP 1: Capture user text from any structure
let text =
  safeGet($json, "text") ||
  safeGet($json, "message.text") ||
  safeGet($json, "data.text") ||
  safeGet($json, "result.text") ||
  safeGet($json, "prompt") ||
  JSON.stringify($json) ||
  "";

// Convert to string safely
text = text.toString();

// STEP 2: Normalize/clean text
const clean = text
  .replace(/[^\dA-Za-z+\s]/g, " ")  // remove emojis & weird chars
  .replace(/\s+/g, " ")             // collapse multiple spaces
  .trim();

// STEP 3: Extract phone number
const phoneRegex = /(?:\+?91[\s-]*)?(\d{3})[\s-]?(\d{3})[\s-]?(\d{4})/;
const match = clean.match(phoneRegex);

let phone = null;
if (match) {
  phone = match[1] + match[2] + match[3]; // always 10 digits
}

// STEP 4: Extract instruction (remove phone + call words)
let instruction = clean
  .replace(phoneRegex, "")
  .replace(/\b(call|kal|kall|col|phone|dial|ring|msg|message|get in touch)\b/gi, "")
  .trim();

// Auto-correct
instruction = instruction
  .replace(/\bgie\b/gi, "give")
  .replace(/\bdetil\b/gi, "detail")
  .replace(/\bcmpny\b/gi, "company")
  .trim();

// Default if empty
if (!instruction || instruction.length < 2) {
  instruction = "call the customer";
}

// STEP 5: Final JSON return
return {
  raw: clean,
  action: "make_call",
  phone,
  firstMessage: instruction
};

// 1️⃣ Get raw text from previous node
let raw = $json.data || $json.response || $json.text || $json.output || $json || "";

// Convert entire object to string if needed
raw = typeof raw === "string" ? raw : JSON.stringify(raw);

// 2️⃣ Unescape \n, \" etc. (critical for your case)
try {
    raw = raw.replace(/\\n/g, '\n').replace(/\\"/g, '"');
} catch (e) {}

// 3️⃣ Extract JSON block
const match = raw.match(/\{[\s\S]*\}/);
if (!match) {
  return [{ json: { error: "No JSON detected", raw: raw } }];
}

let parsed;
try {
  parsed = JSON.parse(match[0]);
} catch (err) {
  return [{ json: { error: "JSON parse error: " + err.message, raw: raw } }];
}

// 4️⃣ Required fields
const fields = [
  "customerName", "customerPhone", "customerWhatsApp", "requirement",
  "propertyType", "budget", "city", "locationDetails", "timeline",
  "intentLevel", "objections", "followUpDate", "email",
  "callOutcome", "nextSteps", "summary"
];

// 5️⃣ Fill missing fields with ""
let result = {};
for (const f of fields) {
    result[f] = parsed[f] ?? "";
}

// 6️⃣ Clean phone numbers
result.customerPhone = result.customerPhone.toString().replace(/[^0-9]/g, "");
result.customerWhatsApp = result.customerWhatsApp.toString().replace(/[^0-9]/g, "");

// 7️⃣ Return final cleaned JSON
return [{ json: result }];

